Subroutine SafeDivide(a As Integer, b As Integer) As Result<Integer, String>
  If b = 0 Then
    Return Failure("Cannot divide by 0");
  EndIf
  Return Success(a Div b);
EndSubroutine

Algorithm Division
  Define a, b As Integer;
  Read a;
  Read b;
  Switch SafeDivide(a, b) Do
    Success(quotient): Write quotient;
    Failure(reason): Write reason;
  EndSwitch
EndAlgorithm
